head.script:
scwin.onpageload = function() {

    var json = [{"radioCol":"Y"},{"radioCol":"Text"}];
    dlt_list1.setJSON(json);

    //var json2 = [{"radioCol":"rdo", "radioY":"", "radioN":""},{"radioCol":"text", "radioY":"", "radioN":""}];
    //dlt_list2.setJSON(json2);

    scwin.fn_setInputType();
    //scwin.fn_setInputType2();  

};

/* 질문) setCellInputType API를 이용하여 동적으로 컬럼 타입을 변경하려 할 때 dataList에 바인딩된 컬럼이 없다면 
            사용 할 수 없나요 ? */
scwin.fn_setInputType = function(){
    var rtnInfoTxt = {inputType: "text"};

    var rtnInfo1 = {inputType: "radio"
                   ,options : {groupName:"radioCol", groupValue:"Y"}
                   };

    var rtnInfo2 = {inputType: "radio"
                   ,options : {groupName:"radioCol", groupValue:"N"}
                   }; 

    var _cnt = dlt_list1.getTotalRow();

    for(var i=0; i<_cnt; i++){
        var _radioCol = dlt_list1.getCellData(i, "radioCol");
        if(_radioCol == "Y"){
            grdDyp1.setCellInputType(i, "radioY", rtnInfo1);
            grdDyp1.setCellInputType(i, "radioN", rtnInfo2);
        }else{
            grdDyp1.setCellInputType(i, "radioY", rtnInfoTxt);
            grdDyp1.setCellInputType(i, "radioN", rtnInfoTxt);
        }
    }                        
};

		scwin.checkVal1 = function() {
			return WebSquare.wUnit.getDomById('grdDyp1_cell_0_1').children[0].nodeName == 'INPUT';
		}
		scwin.checkVal2 = function() {
			return WebSquare.wUnit.getDomById('grdDyp1_cell_0_2').children[0].nodeName == 'INPUT';
		}
		scwin.unitTest = function() {
			//Unit
			WebSquare.wUnit.start();
			WebSquare.wUnit.addCommand("pause", "500");
			WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
			WebSquare.wUnit.addCommand("pause", "500");
			WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
			WebSquare.wUnit.addCommand("pause", "500");

			//Run test and stop
			WebSquare.wUnit.run();
			WebSquare.wUnit.stop();
		}	
		scwin.unitTest()
